/**
 * The operator's commands, against a real Postgres through the same store the CLI uses.
 *
 * Every password here is generated by the code under test or is obviously fake.
 */
import pg from "pg";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createPasswordHasher, checkPasswordShape, type PasswordHasher } from "../password";
import {
  PASSWORD_GRACE_ATTEMPTS,
  PASSWORD_LOCK_MS,
  PASSWORD_MAX_FAILED_ATTEMPTS,
} from "../store/postgres/credentials";
import { addDevice, seedFixture, type Fixture } from "../testing/fixtures";
import { credentialRowIn } from "../testing/password-kit";
import { createTestStore, type TestStore } from "../testing/pg";
import {
  AccountArgsError,
  createAccount,
  disableAccount,
  enableAccount,
  formatCreated,
  formatList,
  formatReset,
  listAccounts,
  parseAccountArgs,
  resetPassword,
  setAccountEndpoint,
  setAccountRole,
  type AccountDeps,
} from "./index";

let test: TestStore;
let fixture: Fixture;
let hasher: PasswordHasher;
let deps: AccountDeps;

const SLUG = "accounts";

beforeAll(async () => {
  test = await createTestStore();
  // A cap well above what these tests make: the ones that are about the cap use a tenant of their own.
  fixture = await seedFixture(test.store, { slug: SLUG, email: "owner@accounts.test", seatCap: 50 });
  hasher = createPasswordHasher();
  deps = { store: test.store, passwords: hasher, clock: test.store.clock };
}, 180_000);

afterAll(async () => {
  await test?.close();
});

let seq = 0;
function nextName(): { username: string; email: string } {
  seq += 1;
  return { username: `account.person.${seq}`, email: `account.person.${seq}@accounts.test` };
}

async function create(overrides: Partial<Parameters<typeof createAccount>[1]> = {}) {
  return createAccount(deps, {
    tenantSlug: SLUG,
    orgSlug: null,
    ...nextName(),
    role: null,
    displayName: null,
    ...overrides,
  });
}

function audit(action: string) {
  return test.store.tx(fixture.tenant.id, (ops) => ops.audit.list({ tenantId: fixture.tenant.id, action }));
}

describe("create", () => {
  it("makes an active person with a generated initial password they must replace, and stores only its hash", async () => {
    const result = await create({ role: "admin", displayName: "Fake Person" });
    expect(result.ok).toBe(true);
    if (!result.ok) {
      return;
    }
    expect(result.password).toMatch(/^[A-HJ-NP-Za-km-np-z2-9]{4}(-[A-HJ-NP-Za-km-np-z2-9]{4}){4}$/);
    expect(checkPasswordShape(result.password)).toBeNull();
    expect(result.role).toBe("admin");
    expect(result.attached).toBe(false);

    const account = await test.store.tx(fixture.tenant.id, (ops) =>
      ops.credentials.findAccount(fixture.tenant.id, result.username),
    );
    expect(account?.user.status).toBe("active");
    expect(account?.user.role).toBe("admin");
    expect(account?.user.displayName).toBe("Fake Person");
    expect(account?.credential.mustChange).toBe(true);
    // The store never hands the hash back, so a credential cannot even be asked for it.
    expect(JSON.stringify(account)).not.toContain(result.password);
    expect(Object.keys(account?.credential ?? {})).not.toContain("passwordHash");

    // What was stored is the hash of what was printed.
    const reserved = await test.store.tx(fixture.tenant.id, (ops) =>
      ops.credentials.reserveAttempt({
        userId: result.userId,
        now: new Date(),
        maxAttempts: PASSWORD_MAX_FAILED_ATTEMPTS,
        lockMs: PASSWORD_LOCK_MS,
      }),
    );
    expect(reserved.kind).toBe("reserved");
    if (reserved.kind === "reserved") {
      expect(await hasher.verify(result.password, reserved.secret)).toBe(true);
      expect(await hasher.verify(`${result.password}x`, reserved.secret)).toBe(false);
    }
  }, 30_000);

  it("writes an audit row that names the action and never the password or the hash", async () => {
    const result = await create();
    expect(result.ok).toBe(true);
    if (!result.ok) {
      return;
    }
    const rows = (await audit("account.created")).filter((row) => row.targetId === result.userId);
    expect(rows).toHaveLength(1);
    expect(rows[0].actorKind).toBe("support");
    expect(rows[0].after).toMatchObject({
      username: result.username,
      role: "member",
      must_change: true,
      attached: false,
    });
    expect(JSON.stringify(rows[0])).not.toContain(result.password);
  });

  it("prints the password once, in the create report and nowhere in the list", async () => {
    const result = await create();
    expect(result.ok).toBe(true);
    if (!result.ok) {
      return;
    }
    expect(formatCreated(result)).toContain(result.password);
    const listed = await listAccounts(deps, { tenantSlug: SLUG, orgSlug: null });
    expect(listed.ok).toBe(true);
    if (listed.ok) {
      const text = formatList(listed);
      expect(text).toContain(result.username);
      expect(text).toContain("must change");
      expect(text).not.toContain(result.password);
      expect(text).not.toMatch(/scrypt/i);
    }
  });

  it("refuses when the org has no seat left, and writes nothing", async () => {
    // A tenant of its own with a cap of two: the seeded owner and one more.
    const small = await seedFixture(test.store, { slug: "smallorg", email: "owner@smallorg.test", seatCap: 2 });
    const smallDeps = deps;
    const base = { tenantSlug: small.tenant.slug, orgSlug: null, role: null, displayName: null };
    const second = await createAccount(smallDeps, {
      ...base,
      username: "second.person",
      email: "second@smallorg.test",
    });
    expect(second.ok).toBe(true);

    const third = await createAccount(smallDeps, { ...base, username: "third.person", email: "third@smallorg.test" });
    expect(third).toEqual({ ok: false, reason: "seat_cap_reached" });
    const people = await test.store.tx(small.tenant.id, (ops) =>
      ops.credentials.listPeople(small.tenant.id, small.org.id),
    );
    expect(people.map((person) => person.user.email).sort()).toEqual(["owner@smallorg.test", "second@smallorg.test"]);
    expect(
      await test.store.tx(small.tenant.id, (ops) => ops.credentials.findAccount(small.tenant.id, "third.person")),
    ).toBeNull();
  }, 60_000);

  it("attaches a password to the active owner `seed` made, keeps their role, and takes no new seat", async () => {
    const solo = await seedFixture(test.store, { slug: "soloorg", email: "owner@soloorg.test", seatCap: 1 });
    const base = { tenantSlug: solo.tenant.slug, orgSlug: null, displayName: null };

    // A new person would not fit (cap of one, held by the owner).
    expect(
      await createAccount(deps, { ...base, username: "new.person", email: "new@soloorg.test", role: null }),
    ).toEqual({ ok: false, reason: "seat_cap_reached" });

    // Asking for a role they do not hold is a refusal, not a quiet demotion.
    expect(
      await createAccount(deps, { ...base, username: "the.owner", email: "owner@soloorg.test", role: "member" }),
    ).toEqual({ ok: false, reason: "role_mismatch" });

    const attached = await createAccount(deps, {
      ...base,
      username: "the.owner",
      email: "owner@soloorg.test",
      role: null,
    });
    expect(attached.ok).toBe(true);
    if (attached.ok) {
      expect(attached.attached).toBe(true);
      expect(attached.role).toBe("owner");
      expect(attached.userId).toBe(solo.user.id);
    }
  }, 60_000);

  it("ends every session an existing person already holds when it gives them a password, and none for a new person", async () => {
    const solo = await seedFixture(test.store, { slug: "attachsessions", email: "owner@attachsessions.test", seatCap: 5 });
    const base = { tenantSlug: solo.tenant.slug, orgSlug: null, displayName: null };

    // The owner `seed` made has been signed in before: a device, a portal session, a browser cookie's version.
    const device = await addDevice(test.store, solo, solo.user);
    await test.store.tx(solo.tenant.id, (ops) =>
      ops.sessions.create({
        tenantId: solo.tenant.id,
        orgId: solo.org.id,
        userId: solo.user.id,
        deviceId: device.id,
      }),
    );
    const versionBefore = await test.store.tx(solo.tenant.id, (ops) => ops.webSessions.version(solo.user.id));
    expect(await test.store.tx(solo.tenant.id, (ops) => ops.sessions.listLiveForUser(solo.user.id))).toHaveLength(1);

    const attached = await createAccount(deps, {
      ...base,
      username: "the.owner",
      email: "owner@attachsessions.test",
      role: null,
    });
    expect(attached.ok).toBe(true);

    // A session that predates the credential would be a way past the forced change: it is gone.
    expect(await test.store.tx(solo.tenant.id, (ops) => ops.sessions.listLiveForUser(solo.user.id))).toHaveLength(0);
    expect(await test.store.tx(solo.tenant.id, (ops) => ops.webSessions.version(solo.user.id))).toBe(versionBefore + 1);
    const rows = (
      await test.store.tx(solo.tenant.id, (ops) =>
        ops.audit.list({ tenantId: solo.tenant.id, action: "account.created" }),
      )
    ).filter((row) => row.targetId === solo.user.id);
    expect(rows).toHaveLength(1);
    expect(rows[0].after).toMatchObject({ attached: true, sessions_ended: 1 });

    // A person who did not exist has nothing to end, and nothing is bumped for them.
    const fresh = await createAccount(deps, {
      ...base,
      username: "brand.new",
      email: "brand.new@attachsessions.test",
      role: null,
    });
    expect(fresh.ok).toBe(true);
    if (fresh.ok) {
      expect(await test.store.tx(solo.tenant.id, (ops) => ops.webSessions.version(fresh.userId))).toBe(1);
    }
  }, 60_000);

  it("refuses each state it cannot honour, with a reason an operator can act on", async () => {
    const first = await create();
    expect(first.ok).toBe(true);
    if (!first.ok) {
      return;
    }
    const fresh = nextName();

    expect(await create({ ...nextName(), username: first.username })).toEqual({ ok: false, reason: "username_taken" });
    expect(await create({ ...fresh, email: first.email })).toEqual({ ok: false, reason: "already_has_account" });
    expect(await create({ tenantSlug: "nobody" })).toEqual({ ok: false, reason: "unknown_tenant" });
    expect(await create({ orgSlug: "no-such-org" })).toEqual({ ok: false, reason: "unknown_org" });

    // A person who was disabled comes back through `enable`, not through a second account.
    const disabled = await create();
    if (disabled.ok) {
      await disableAccount(deps, { tenantSlug: SLUG, person: { by: "username", username: disabled.username } });
      expect(await create({ ...nextName(), email: disabled.email })).toEqual({ ok: false, reason: "user_disabled" });
    }

    // An invited person is a code-mode leftover: there is no invite to redeem in this mode.
    const invitedEmail = "left.over@accounts.test";
    await test.store.tx(fixture.tenant.id, (ops) =>
      ops.users.create({ tenantId: fixture.tenant.id, orgId: fixture.org.id, email: invitedEmail, status: "invited" }),
    );
    expect(await create({ ...nextName(), email: invitedEmail })).toEqual({ ok: false, reason: "user_invited" });
  }, 120_000);

  it("asks which org when a tenant has two", async () => {
    const two = await seedFixture(test.store, { slug: "twoorgs", email: "owner@twoorgs.test" });
    await test.store.tx(two.tenant.id, (ops) =>
      ops.orgs.create({ tenantId: two.tenant.id, name: "Second", slug: "second", seatCap: 5 }),
    );
    const base = { tenantSlug: "twoorgs", displayName: null, role: null };
    expect(
      await createAccount(deps, { ...base, orgSlug: null, username: "someone.new", email: "new@twoorgs.test" }),
    ).toEqual({
      ok: false,
      reason: "choose_org",
    });
    const named = await createAccount(deps, {
      ...base,
      orgSlug: "second",
      username: "someone.new",
      email: "new@twoorgs.test",
    });
    expect(named.ok).toBe(true);
  }, 60_000);
});

describe("reset-password", () => {
  it("replaces the password, clears a lock, makes them choose again, and ends their sessions", async () => {
    const made = await create();
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    // A chosen password, a lock, and a live session on a device.
    const chosen = await hasher.hash("chosen-fake-password-2");
    await test.store.tx(fixture.tenant.id, async (ops) => {
      await ops.credentials.setPassword({ userId: made.userId, secret: chosen, mustChange: false, now: new Date() });
    });
    for (let attempt = 0; attempt < PASSWORD_MAX_FAILED_ATTEMPTS; attempt += 1) {
      await test.store.tx(fixture.tenant.id, (ops) =>
        ops.credentials.reserveAttempt({
          userId: made.userId,
          now: new Date(),
          maxAttempts: PASSWORD_MAX_FAILED_ATTEMPTS,
          lockMs: PASSWORD_LOCK_MS,
        }),
      );
    }
    const user = await test.store.tx(fixture.tenant.id, (ops) => ops.users.findById(made.userId));
    if (!user) {
      throw new Error("the person made a moment ago is not there");
    }
    const device = await addDevice(test.store, fixture, user);
    await test.store.tx(fixture.tenant.id, (ops) =>
      ops.sessions.create({
        tenantId: fixture.tenant.id,
        orgId: fixture.org.id,
        userId: made.userId,
        deviceId: device.id,
      }),
    );
    const versionBefore = await test.store.tx(fixture.tenant.id, (ops) => ops.webSessions.version(made.userId));

    const reset = await resetPassword(deps, {
      tenantSlug: SLUG,
      person: { by: "email", email: made.email.toUpperCase() },
    });
    expect(reset.ok).toBe(true);
    if (!reset.ok) {
      return;
    }
    expect(reset.password).not.toBe(made.password);
    expect(reset.sessionsEnded).toBe(1);
    expect(formatReset(reset)).toContain(reset.password);

    const state = await test.store.tx(fixture.tenant.id, async (ops) => ({
      credential: await ops.credentials.findByUserId(made.userId),
      live: await ops.sessions.listLiveForUser(made.userId),
      version: await ops.webSessions.version(made.userId),
      reserved: await ops.credentials.reserveAttempt({
        userId: made.userId,
        now: new Date(),
        maxAttempts: PASSWORD_MAX_FAILED_ATTEMPTS,
        lockMs: PASSWORD_LOCK_MS,
      }),
    }));
    expect(state.credential?.mustChange).toBe(true);
    expect(state.live).toHaveLength(0);
    expect(state.version).toBe(versionBefore + 1);
    // The lock is gone (this reserved an attempt instead of being refused), and the new password is
    // the one stored: neither the first generated one nor the one they had chosen works.
    expect(state.reserved.kind).toBe("reserved");
    if (state.reserved.kind === "reserved") {
      expect(await hasher.verify(reset.password, state.reserved.secret)).toBe(true);
      expect(await hasher.verify(made.password, state.reserved.secret)).toBe(false);
      expect(await hasher.verify("chosen-fake-password-2", state.reserved.secret)).toBe(false);
    }
    const rows = (await audit("account.password_reset")).filter((row) => row.targetId === made.userId);
    expect(rows).toHaveLength(1);
    expect(JSON.stringify(rows[0])).not.toContain(reset.password);
  }, 60_000);

  it("clears the failed attempts, the slots taken under the lock and the lock, and says so", async () => {
    const made = await create();
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    const now = new Date();
    for (let attempt = 0; attempt < PASSWORD_MAX_FAILED_ATTEMPTS + PASSWORD_GRACE_ATTEMPTS; attempt += 1) {
      await test.store.tx(fixture.tenant.id, (ops) =>
        ops.credentials.reserveAttempt({
          userId: made.userId,
          now,
          maxAttempts: PASSWORD_MAX_FAILED_ATTEMPTS,
          lockMs: PASSWORD_LOCK_MS,
          graceAttempts: PASSWORD_GRACE_ATTEMPTS,
        }),
      );
    }
    const before = await credentialRowIn(test.database, fixture.tenant.id, made.userId);
    expect([before.failedAttempts, before.graceAttempts]).toEqual([
      PASSWORD_MAX_FAILED_ATTEMPTS,
      PASSWORD_GRACE_ATTEMPTS,
    ]);
    expect(before.lockedUntil).not.toBeNull();

    const reset = await resetPassword(deps, { tenantSlug: SLUG, person: { by: "username", username: made.username } });
    expect(reset.ok).toBe(true);
    if (!reset.ok) {
      return;
    }
    const after = await credentialRowIn(test.database, fixture.tenant.id, made.userId);
    expect([after.failedAttempts, after.graceAttempts, after.lockedUntil]).toEqual([0, 0, null]);
    expect(after.mustChange).toBe(true);

    // The operator is told, in the words of what was cleared.
    const text = formatReset(reset);
    expect(text).toContain("failed attempts");
    expect(text).toContain("lock");
    expect(text).toMatch(/cleared/);
  }, 60_000);

  it("says so for somebody who has no account", async () => {
    expect(
      await resetPassword(deps, { tenantSlug: SLUG, person: { by: "username", username: "nobody.at.all" } }),
    ).toEqual({
      ok: false,
      reason: "not_found",
    });
    expect(await resetPassword(deps, { tenantSlug: "nobody", person: { by: "username", username: "x.y.z" } })).toEqual({
      ok: false,
      reason: "unknown_tenant",
    });
  });
});

describe("disable and enable", () => {
  it("disables a person and ends every session, refuses the last owner, and refuses a second disable", async () => {
    const made = await create({ role: "admin" });
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    const versionBefore = await test.store.tx(fixture.tenant.id, (ops) => ops.webSessions.version(made.userId));
    const result = await disableAccount(deps, {
      tenantSlug: SLUG,
      person: { by: "username", username: made.username },
    });
    expect(result.ok).toBe(true);
    const after = await test.store.tx(fixture.tenant.id, async (ops) => ({
      user: await ops.users.findById(made.userId),
      version: await ops.webSessions.version(made.userId),
    }));
    expect(after.user?.status).toBe("disabled");
    expect(after.version).toBe(versionBefore + 1);
    expect((await audit("account.disabled")).some((row) => row.targetId === made.userId)).toBe(true);

    expect(
      await disableAccount(deps, { tenantSlug: SLUG, person: { by: "username", username: made.username } }),
    ).toEqual({
      ok: false,
      reason: "already_disabled",
    });

    // The seeded owner has no password, so `disable` cannot find them by username; the last-owner
    // rule is the same either way, so give them one first.
    const attached = await createAccount(deps, {
      tenantSlug: SLUG,
      orgSlug: null,
      username: "the.only.owner",
      email: "owner@accounts.test",
      role: null,
      displayName: null,
    });
    expect(attached.ok).toBe(true);
    expect(
      await disableAccount(deps, { tenantSlug: SLUG, person: { by: "username", username: "the.only.owner" } }),
    ).toEqual({
      ok: false,
      reason: "last_owner",
    });
  }, 60_000);

  it("enables a disabled person, refuses one who is not disabled, and refuses when no seat is left", async () => {
    const tight = await seedFixture(test.store, { slug: "tightorg", email: "owner@tightorg.test", seatCap: 2 });
    const base = { tenantSlug: tight.tenant.slug, orgSlug: null, role: null, displayName: null };
    const one = await createAccount(deps, { ...base, username: "one.person", email: "one@tightorg.test" });
    expect(one.ok).toBe(true);
    const person = { by: "username", username: "one.person" } as const;

    expect(await enableAccount(deps, { tenantSlug: tight.tenant.slug, person })).toEqual({
      ok: false,
      reason: "not_disabled",
    });
    expect((await disableAccount(deps, { tenantSlug: tight.tenant.slug, person })).ok).toBe(true);

    // Their seat goes to somebody else while they are away.
    const taken = await createAccount(deps, { ...base, username: "other.person", email: "other@tightorg.test" });
    expect(taken.ok).toBe(true);
    expect(await enableAccount(deps, { tenantSlug: tight.tenant.slug, person })).toEqual({
      ok: false,
      reason: "seat_cap_reached",
    });

    await test.store.tx(tight.tenant.id, (ops) => ops.orgs.setSeatCap(tight.org.id, 3));
    const back = await enableAccount(deps, { tenantSlug: tight.tenant.slug, person });
    expect(back.ok).toBe(true);
    expect(
      (await test.store.tx(tight.tenant.id, (ops) => ops.users.findByEmail(tight.tenant.id, "one@tightorg.test")))
        ?.status,
    ).toBe("active");
  }, 60_000);
});

describe("set-role", () => {
  it("changes a role with the existing rules, last owner included", async () => {
    const made = await create();
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    const changed = await setAccountRole(deps, {
      tenantSlug: SLUG,
      person: { by: "username", username: made.username },
      role: "admin",
    });
    expect(changed).toMatchObject({ ok: true, from: "member", to: "admin" });
    expect(
      await setAccountRole(deps, {
        tenantSlug: SLUG,
        person: { by: "username", username: made.username },
        role: "admin",
      }),
    ).toEqual({ ok: false, reason: "same_role" });
    expect(
      await setAccountRole(deps, {
        tenantSlug: SLUG,
        person: { by: "username", username: "nobody.here" },
        role: "admin",
      }),
    ).toEqual({ ok: false, reason: "not_found" });
  }, 60_000);
});

describe("list", () => {
  it("shows who is locked, who has no password and who must change theirs, and nobody's secrets", async () => {
    const made = await create();
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    for (let attempt = 0; attempt < PASSWORD_MAX_FAILED_ATTEMPTS; attempt += 1) {
      await test.store.tx(fixture.tenant.id, (ops) =>
        ops.credentials.reserveAttempt({
          userId: made.userId,
          now: new Date(),
          maxAttempts: PASSWORD_MAX_FAILED_ATTEMPTS,
          lockMs: PASSWORD_LOCK_MS,
        }),
      );
    }
    const listed = await listAccounts(deps, { tenantSlug: SLUG, orgSlug: null });
    expect(listed.ok).toBe(true);
    if (!listed.ok) {
      return;
    }
    const lines = formatList(listed).split("\n");
    const mine = lines.find((line) => line.startsWith(made.username));
    expect(mine).toMatch(/locked|until \d{4}-\d{2}-\d{2}T/);
    expect(mine).toContain("must change");
    // The seeded owner is on record with no password.
    expect(lines.find((line) => line.includes("owner@accounts.test"))).toMatch(/no password|chosen|must change/);
    expect(lines[0]).toMatch(/seats \d+ of 50 on record/);
  }, 60_000);

  it("shows how many times each account was locked in the last 24 hours, and not the older ones", async () => {
    const hit = await create();
    const quiet = await create();
    expect(hit.ok && quiet.ok).toBe(true);
    if (!hit.ok || !quiet.ok) {
      return;
    }
    const lockRow = (userId: string) =>
      test.store.tx(fixture.tenant.id, (ops) =>
        ops.audit.append({
          tenantId: fixture.tenant.id,
          orgId: fixture.org.id,
          actorKind: "system",
          action: "password.locked",
          targetKind: "user",
          targetId: userId,
          reasonCode: "too_many_failures",
        }),
      );
    await lockRow(hit.userId);
    await lockRow(hit.userId);
    await lockRow(hit.userId);

    // A lock from the day before yesterday: the audit table is append-only, so it is written the way an
    // old row got there, with its own time, as the database's owner.
    const admin = new pg.Client({ connectionString: test.database.url });
    await admin.connect();
    try {
      await admin.query(
        `INSERT INTO audit_log (tenant_id, org_id, actor_kind, action, target_kind, target_id, reason_code, created_at)
         VALUES ($1, $2, 'system', 'password.locked', 'user', $3, 'too_many_failures', now() - interval '25 hours')`,
        [fixture.tenant.id, fixture.org.id, hit.userId],
      );
    } finally {
      await admin.end();
    }

    const listed = await listAccounts(deps, { tenantSlug: SLUG, orgSlug: null });
    expect(listed.ok).toBe(true);
    if (!listed.ok) {
      return;
    }
    const lines = formatList(listed).split("\n");
    const header = lines.find((line) => line.startsWith("username")) ?? "";
    const cells = (line: string) => line.split(/\s{2,}/);
    const column = cells(header).indexOf("locks 24h");
    expect(column).toBeGreaterThan(-1);
    expect(cells(lines.find((line) => line.startsWith(hit.username)) ?? "")[column]).toBe("3");
    expect(cells(lines.find((line) => line.startsWith(quiet.username)) ?? "")[column]).toBe("0");
  }, 60_000);
});

describe("enable", () => {
  it("lets a person back in with no count or lock left by attempts made on them while they were disabled", async () => {
    const made = await create();
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    const target = { tenantSlug: SLUG, person: { by: "username", username: made.username } } as const;
    expect((await disableAccount(deps, target)).ok).toBe(true);
    // What the sign-in does for an attempt on a disabled person: it is counted, so that it is bounded.
    for (let attempt = 0; attempt < PASSWORD_MAX_FAILED_ATTEMPTS; attempt += 1) {
      await test.store.tx(fixture.tenant.id, (ops) =>
        ops.credentials.reserveAttempt({
          userId: made.userId,
          now: new Date(),
          maxAttempts: PASSWORD_MAX_FAILED_ATTEMPTS,
          lockMs: PASSWORD_LOCK_MS,
        }),
      );
    }
    expect((await credentialRowIn(test.database, fixture.tenant.id, made.userId)).lockedUntil).not.toBeNull();

    expect((await enableAccount(deps, target)).ok).toBe(true);
    const after = await credentialRowIn(test.database, fixture.tenant.id, made.userId);
    expect([after.failedAttempts, after.graceAttempts, after.lockedUntil]).toEqual([0, 0, null]);
    // The password they had is the one they still have.
    expect(after.mustChange).toBe(true);
  }, 60_000);
});

describe("set-endpoint (Nultron admin only)", () => {
  it("assigns a gateway endpoint at create time, updates it, clears it, and shows it in list", async () => {
    const made = await create({ gatewayEndpoint: "https://gw-alpha.example/v1/" });
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    expect(made.gatewayEndpoint).toBe("https://gw-alpha.example/v1");
    expect(formatCreated(made)).toContain("endpoint   https://gw-alpha.example/v1");

    const listed1 = await listAccounts(deps, { tenantSlug: SLUG, orgSlug: null });
    expect(listed1.ok).toBe(true);
    if (listed1.ok) {
      expect(formatList(listed1)).toContain("https://gw-alpha.example/v1");
    }

    const updated = await setAccountEndpoint(deps, {
      tenantSlug: SLUG,
      person: { by: "username", username: made.username },
      gatewayEndpoint: "https://gw-beta.example/v1",
    });
    expect(updated).toEqual({
      ok: true,
      username: made.username,
      email: made.email,
      userId: made.userId,
      from: "https://gw-alpha.example/v1",
      to: "https://gw-beta.example/v1",
    });

    const same = await setAccountEndpoint(deps, {
      tenantSlug: SLUG,
      person: { by: "username", username: made.username },
      gatewayEndpoint: "https://gw-beta.example/v1/",
    });
    expect(same).toEqual({ ok: false, reason: "same_endpoint" });

    const cleared = await setAccountEndpoint(deps, {
      tenantSlug: SLUG,
      person: { by: "email", email: made.email },
      gatewayEndpoint: null,
    });
    expect(cleared).toEqual({
      ok: true,
      username: made.username,
      email: made.email,
      userId: made.userId,
      from: "https://gw-beta.example/v1",
      to: null,
    });

    const rows = (await audit("account.gateway_endpoint_updated")).filter((row) => row.targetId === made.userId);
    expect(rows).toHaveLength(2);
    // Audit rows are returned newest-first.
    expect(rows[0].before).toEqual({ gateway_endpoint: "https://gw-beta.example/v1" });
    expect(rows[0].after).toMatchObject({ gateway_endpoint: null });
    expect(rows[1].before).toEqual({ gateway_endpoint: "https://gw-alpha.example/v1" });
    expect(rows[1].after).toMatchObject({ gateway_endpoint: "https://gw-beta.example/v1" });
  }, 60_000);

  it("rejects invalid non-HTTPS or credentialed endpoints", async () => {
    const made = await create();
    expect(made.ok).toBe(true);
    if (!made.ok) {
      return;
    }
    for (const bad of [
      "http://external.example/v1",
      "https://user:pass@gw.example/v1",
      "https://gw.example/v1?foo=bar",
      "not-a-url",
    ]) {
      const res = await setAccountEndpoint(deps, {
        tenantSlug: SLUG,
        person: { by: "username", username: made.username },
        gatewayEndpoint: bad,
      });
      expect(res, bad).toEqual({ ok: false, reason: "invalid_gateway_endpoint" });
    }
  }, 30_000);
});

describe("the argument parser", () => {
  it("reads each command and defaults the tenant to nultron", () => {
    expect(parseAccountArgs(["create", "--username", "Alice.Fake", "--email", "Alice@Example.Test"])).toEqual({
      command: "create",
      tenantSlug: "nultron",
      orgSlug: null,
      username: "alice.fake",
      email: "alice@example.test",
      role: null,
      displayName: null,
      gatewayEndpoint: null,
    });
    expect(
      parseAccountArgs([
        "--",
        "create",
        "--username=bob.fake",
        "--email=bob@example.test",
        "--role",
        "admin",
        "--name",
        "Bob",
        "--gateway-endpoint",
        "https://gw.example/v1/",
      ]),
    ).toMatchObject({
      role: "admin",
      displayName: "Bob",
      gatewayEndpoint: "https://gw.example/v1",
    });
    expect(
      parseAccountArgs([
        "set-endpoint",
        "--username",
        "alice.fake",
        "--gateway-endpoint",
        "https://gw-custom.example/v1/",
      ]),
    ).toEqual({
      command: "set-endpoint",
      tenantSlug: "nultron",
      orgSlug: null,
      person: { by: "username", username: "alice.fake" },
      gatewayEndpoint: "https://gw-custom.example/v1",
    });
    expect(parseAccountArgs(["set-endpoint", "--email", "a@example.test", "--clear"])).toEqual({
      command: "set-endpoint",
      tenantSlug: "nultron",
      orgSlug: null,
      person: { by: "email", email: "a@example.test" },
      gatewayEndpoint: null,
    });
    expect(parseAccountArgs(["reset-password", "--email", "x@example.test", "--tenant", "hyp"])).toEqual({
      command: "reset-password",
      tenantSlug: "hyp",
      orgSlug: null,
      person: { by: "email", email: "x@example.test" },
    });
    expect(parseAccountArgs(["set-role", "--username", "alice.fake", "--role", "owner"])).toMatchObject({
      command: "set-role",
      role: "owner",
    });
    expect(parseAccountArgs(["list", "--org-slug", "Kyo"])).toMatchObject({ command: "list", orgSlug: "kyo" });
  });

  it("refuses what cannot be run, in words", () => {
    const cases: string[][] = [
      [],
      ["create"],
      ["create", "--username", "ab", "--email", "a@example.test"],
      ["create", "--username", "has space", "--email", "a@example.test"],
      ["create", "--username", "a@b.test", "--email", "a@example.test"],
      ["create", "--username", "alice.fake", "--email", "not-an-address"],
      ["create", "--username", "alice.fake", "--email", "a@example.test", "--role", "root"],
      ["reset-password"],
      ["reset-password", "--username", "alice.fake", "--email", "a@example.test"],
      ["set-role", "--username", "alice.fake"],
      ["frobnicate"],
      ["list", "extra"],
      ["list", "--tenant", "Bad Tenant"],
      ["create", "--username"],
      ["create", "--username", "alice.fake", "--email", "a@example.test", "--gateway-endpoint", "http://bad.example/v1"],
      ["set-endpoint", "--username", "alice.fake"],
      ["set-endpoint", "--username", "alice.fake", "--clear", "--gateway-endpoint", "https://gw.example/v1"],
    ];
    for (const argv of cases) {
      expect(() => parseAccountArgs(argv), argv.join(" ")).toThrow(AccountArgsError);
    }
  });
});
